package com.riskguard.transaction.service;
import com.fasterxml.jackson.core.type.TypeReference; import com.fasterxml.jackson.databind.ObjectMapper; import com.riskguard.transaction.api.dto.*; import com.riskguard.transaction.domain.FraudAnalysis; import com.riskguard.transaction.repository.FraudAnalysisRepository; import java.util.List; import java.util.UUID; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class TransactionDetailsService { private final TransactionService transactions; private final FraudAnalysisRepository analyses; private final FraudReviewService reviews; private final ObjectMapper mapper; public TransactionDetailsService(TransactionService transactions,FraudAnalysisRepository analyses,FraudReviewService reviews,ObjectMapper mapper){this.transactions=transactions;this.analyses=analyses;this.reviews=reviews;this.mapper=mapper;}
 @Transactional(readOnly=true) public TransactionDetailsDtos.Response get(UUID userId,UUID id,boolean elevated){TransactionDtos.Response tx=transactions.get(userId,id,elevated); FraudAnalysis analysis=analyses.findByTransactionId(id).orElse(null); List<String> reasons=analysis==null?List.of():parse(analysis.getReasons()); String correlation=analysis==null?null:analysis.getCorrelationId(); return new TransactionDetailsDtos.Response(tx,reasons,correlation,transactions.history(userId,id,elevated),reviews.list(id));}
 private List<String> parse(String raw){try{return mapper.readValue(raw,new TypeReference<List<String>>(){});}catch(Exception e){return List.of();}}
}
